def solve_game(N):
    """
    Determines the winning status for the current player starting at state n,
    where DP[n] = 1 means Win, and DP[n] = 0 means Lose.
    The player who reaches N wins.
    We calculate DP[n] backwards from N-1 down to 2.
    """
    if N < 4:
        return None 

    # DP array size N+1, initialized to a placeholder value (e.g., -1)
    DP = {} 

    # Iterate backwards from N-1 down to 2
    for n in range(N - 1, 1, -1):

        can_win = False

        # Check move n+1
        n_plus_1 = n + 1
        if n_plus_1 <= N:
            if n_plus_1 == N:
                # Immediate win
                can_win = True
            else:
                # Check if moving to n+1 leads to a losing position (DP[n+1] == 0)
                if DP[n_plus_1] == 0:
                    can_win = True

        if can_win:
            DP[n] = 1
            continue

        # Check move 2n
        n_times_2 = 2 * n
        if n_times_2 <= N:
            if n_times_2 == N:
                # Immediate win
                can_win = True
            else:
                # Check if moving to 2n leads to a losing position (DP[2n] == 0)
                if DP[n_times_2] == 0:
                    can_win = True

        if can_win:
            DP[n] = 1
        else:
            # If no move leads to a loss (or immediate win), this is a losing position
            DP[n] = 0

    # The task asks for the winning status starting at 2 (DP[2]).
    # We want this to be False (Type B).
    return DP.get(2, -1)

# Search for the least N > 400 such that W(2) is False (Type B)
N_start = 401
found_N = None

# Increased search limit significantly
MAX_SEARCH = 5000 

print("Starting search...")
for N in range(N_start, MAX_SEARCH + 1):
    result = solve_game(N)
    if result is False:
        found_N = N
        break
    if N % 1000 == 401:
        print(f"Checked up to N={N}")

print(f"Search finished. The least N > 400 such that W(2) is False is: {found_N}")

